using System.Drawing.Printing;
using GestionMagasin.Application;
using GestionMagasin.Domain;

namespace GestionMagasin.WinForms;

public sealed class SalePanel : UserControl
{
    readonly Utilisateur seller; readonly VenteService sales; readonly ProduitService products; readonly TextBox search=new(); readonly DataGridView catalog=Ui.Grid(),cart=Ui.Grid(); readonly ComboBox payment=new(){DropDownStyle=ComboBoxStyle.DropDownList}; readonly TextBox received=new(); readonly Label total=new(){AutoSize=true,Font=new Font("Segoe UI",14,FontStyle.Bold)}; readonly Button validate=Ui.Button("Valider la vente"); readonly List<CartRow> basket=[];
    public SalePanel(Utilisateur seller,VenteService sales,ProduitService products){this.seller=seller;this.sales=sales;this.products=products;var header=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70};header.Controls.Add(Ui.Title("Nouvelle vente"));search.Width=240;search.PlaceholderText="Rechercher référence ou nom";search.TextChanged+=async(_,_)=>await SearchAsync();header.Controls.Add(search);var add=Ui.Button("Ajouter au panier");add.Click+=(_,_)=>AddSelected();header.Controls.Add(add);Controls.Add(BuildBottom());var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=220};split.Panel1.Controls.Add(catalog);split.Panel2.Controls.Add(cart);Controls.Add(split);Controls.Add(header);catalog.DoubleClick+=(_,_)=>AddSelected();Load+=async(_,_)=>await SearchAsync();}
    Control BuildBottom(){var p=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=80,Padding=new Padding(4)};payment.Items.AddRange(new object[]{ModesPaiement.Especes,ModesPaiement.MobileMoney,ModesPaiement.Carte});payment.SelectedIndex=0;p.Controls.Add(new Label{Text="Paiement",AutoSize=true,Anchor=AnchorStyles.Left});p.Controls.Add(payment);p.Controls.Add(new Label{Text="Reçu FCFA",AutoSize=true,Anchor=AnchorStyles.Left});received.Width=100;p.Controls.Add(received);p.Controls.Add(total);payment.SelectedIndexChanged+=(_,_)=>received.Enabled=payment.SelectedItem?.ToString()==ModesPaiement.Especes;validate.Click+=async(_,_)=>await ValidateAsync();p.Controls.Add(validate);return p;}
    async Task SearchAsync(){var rows=await products.RechercherAsync(new ProduitFilter(search.Text,Actif:true,Disponible:true));catalog.DataSource=rows.Select(x=>new{ProduitId=x.Id,x.Reference,x.Nom,x.PrixVenteFcfa}).ToList();}
    void AddSelected(){if(catalog.CurrentRow?.DataBoundItem is not null){var id=(Guid)catalog.CurrentRow.Cells[0].Value;var row=basket.FirstOrDefault(x=>x.ProduitId==id);if(row is null){var r=catalog.CurrentRow;basket.Add(new CartRow(id,r.Cells[1].Value?.ToString()??"",r.Cells[2].Value?.ToString()??"",Convert.ToInt64(r.Cells[3].Value),1));}else row.Quantite++;RefreshCart();}}
    void RefreshCart(){cart.DataSource=null;cart.DataSource=basket.Select(x=>new{ProduitId=x.ProduitId,x.Reference,x.Nom,x.PrixUnitaireFcfa, x.Quantite,SousTotal=x.PrixUnitaireFcfa*x.Quantite}).ToList();total.Text=$"Total : {basket.Sum(x=>x.PrixUnitaireFcfa*x.Quantite):N0} FCFA";}
    async Task ValidateAsync(){if(validate.Enabled==false)return;validate.Enabled=false;try{var totalValue=basket.Sum(x=>x.PrixUnitaireFcfa*x.Quantite);if(!long.TryParse(received.Text,out var amount))amount=payment.SelectedItem?.ToString()==ModesPaiement.Especes?0:totalValue;var result=await sales.ValiderAsync(seller,basket.Select(x=>new PanierLigne(x.ProduitId,x.Quantite,x.Reference,x.PrixUnitaireFcfa)).ToList(),payment.SelectedItem?.ToString()??ModesPaiement.Especes,amount,TimeZoneInfo.Local.Id);MessageBox.Show($"Vente {result.Numero} enregistrée.\nMonnaie : {result.MonnaieRendueFcfa:N0} FCFA","Vente confirmée",MessageBoxButtons.OK,MessageBoxIcon.Information);basket.Clear();RefreshCart();await SearchAsync();}catch(PrixProduitModifieException ex){if(MessageBox.Show(ex.Message+"\nVoulez-vous relire le catalogue ?","Prix modifié",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes)await SearchAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Vente refusée",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{validate.Enabled=true;}}
    sealed class CartRow(Guid productId,string reference,string nom,long price,int quantity){public Guid ProduitId{get;}=productId;public string Reference{get;}=reference;public string Nom{get;}=nom;public long PrixUnitaireFcfa{get;}=price;public int Quantite{get;set;}=quantity;}
}

public sealed class SalesHistoryPanel : UserControl
{
    readonly Utilisateur actor;readonly VenteService sales;readonly DataGridView grid=Ui.Grid();readonly TextBox search=new();readonly DateTimePicker from=new(){Format=DateTimePickerFormat.Short,Value=DateTime.Today.AddDays(-30)};readonly DateTimePicker to=new(){Format=DateTimePickerFormat.Short,Value=DateTime.Today};
    public SalesHistoryPanel(Utilisateur actor,VenteService sales){this.actor=actor;this.sales=sales;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=76};top.Controls.Add(Ui.Title("Historique des ventes"));search.Width=180;search.PlaceholderText="Numéro de vente";top.Controls.Add(search);top.Controls.Add(from);top.Controls.Add(to);var refresh=Ui.Button("Rechercher");refresh.Click+=async(_,_)=>await LoadAsync();top.Controls.Add(refresh);var detail=Ui.Button("Détail / ticket");detail.Click+=async(_,_)=>await DetailAsync();top.Controls.Add(detail);if(actor.Role==Roles.Administrateur){var cancel=Ui.Button("Annuler");cancel.Click+=async(_,_)=>await CancelAsync();top.Controls.Add(cancel);}Controls.Add(grid);Controls.Add(top);Load+=async(_,_)=>await LoadAsync();}
    async Task LoadAsync(){var rows=await sales.RechercherAsync(actor,search.Text,from.Value.Date,to.Value.Date.AddDays(1),null,null);grid.DataSource=rows.Select(x=>new{x.Id,x.Numero,x.DateMetier,x.Vendeur,x.TotalFcfa,x.ModePaiement,x.Statut}).ToList();}
    async Task DetailAsync(){if(grid.CurrentRow?.Cells[0].Value is not Guid id)return;var detail=await sales.DetailAsync(actor,id);if(detail is null)return;using var f=new SaleDetailForm(detail);f.ShowDialog();}
    async Task CancelAsync(){if(grid.CurrentRow?.Cells[0].Value is not Guid id)return;var motif=Prompt.Show("Motif d'annulation");if(string.IsNullOrWhiteSpace(motif))return;try{await sales.AnnulerAsync(actor,id,motif);await LoadAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Annulation",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}

public sealed class SaleDetailForm : Form
{
    readonly VenteDetail detail;public SaleDetailForm(VenteDetail detail){this.detail=detail;Text=$"Vente {detail.Vente.Numero}";Width=700;Height=450;StartPosition=FormStartPosition.CenterParent;var grid=Ui.Grid();grid.DataSource=detail.Lignes.Select(x=>new{Reference=x.ReferenceSnapshot,Nom=x.NomSnapshot,PrixUnitaireFcfa=x.PrixUnitaireFcfa,Quantite=x.Quantite,SousTotal=x.PrixUnitaireFcfa*x.Quantite}).ToList();var header=new Label{Dock=DockStyle.Top,Height=80,Text=$"Vente : {detail.Vente.Numero}\nVendeur : {detail.Vente.Vendeur}\nTotal : {detail.Vente.TotalFcfa:N0} FCFA - {detail.Vente.ModePaiement}",Padding=new Padding(12),Font=new Font("Segoe UI",11,FontStyle.Bold)};var print=Ui.Button("Imprimer le ticket");print.Click+=(_,_)=>PrintTicket();var p=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55};p.Controls.Add(print);Controls.Add(grid);Controls.Add(p);Controls.Add(header);}
    void PrintTicket(){try{using var document=new PrintDocument();document.PrintPage+=(s,e)=>{using var font=new Font("Consolas",10);var lines=new List<string>{$"Gestion Magasin",detail.Vente.Numero,detail.Vente.DateMetier.ToString("g"),$"Vendeur : {detail.Vente.Vendeur}","------------------------------"};lines.AddRange(detail.Lignes.Select(x=>$"{x.NomSnapshot} x{x.Quantite} {x.PrixUnitaireFcfa*x.Quantite:N0}"));lines.Add("------------------------------");lines.Add($"TOTAL {detail.Vente.TotalFcfa:N0} FCFA");lines.Add($"Paiement : {detail.Vente.ModePaiement}");lines.Add($"Reçu : {detail.MontantRecuFcfa:N0}  Monnaie : {detail.MonnaieRendueFcfa:N0}");e.Graphics.DrawString(string.Join(Environment.NewLine,lines),font,Brushes.Black,new PointF(30,30));};using var dialog=new PrintDialog{Document=document};if(dialog.ShowDialog()==DialogResult.OK)document.Print();}catch(Exception ex){MessageBox.Show($"La vente est conservée. Impression impossible : {ex.Message}","Impression",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}

static class Prompt { public static string Show(string title){using var f=new Form{Text=title,Width=420,Height=160,StartPosition=FormStartPosition.CenterParent};var t=new TextBox{Dock=DockStyle.Top,Margin=new Padding(12)};var b=Ui.Button("OK");b.Click+=(_,_)=>{f.DialogResult=DialogResult.OK;f.Close();};f.Controls.Add(b);f.Controls.Add(t);return f.ShowDialog()==DialogResult.OK?t.Text.Trim():"";} }
